notes.type_tests:
const base: Todo = { title: "Write", done: false, priority: 1 };
updateTodo(base, { done: true });
updateTodo(base, {});
// @ts-expect-error: there is no "color" field
updateTodo(base, { color: "red" });
// @ts-expect-error: done is a boolean
updateTodo(base, { done: "yes" });

notes.front:
**toPublicUser(user)**

Write `toPublicUser(user)`: return the user without `passwordHash`, typed with `Omit` so the compiler also knows the hash is gone.

```ts
interface User {
  id: number;
  name: string;
  passwordHash: string;
}

function toPublicUser(user: User): User {
  return user;
}
```

notes.back:
// Why: Removing the property at run time (rest destructuring) and in the type (Omit) go
// together: either one alone leaves a gap.
// Docs: https://www.typescriptlang.org/docs/handbook/utility-types.html
interface User {
  id: number;
  name: string;
  passwordHash: string;
}

function toPublicUser(user: User): Omit<User, "passwordHash"> {
  const { passwordHash, ...rest } = user;
  return rest;
}

