notes.front:
**countByRole(roles)**

Write `countByRole(roles)`: how many times each role appears, with every role present (0 if absent). Type the result as `Record<Role, number>`.

```ts
type Role = "admin" | "editor" | "viewer";

function countByRole(roles: string[]): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const role of roles) counts[role] = (counts[role] ?? 0) + 1;
  return counts;
}
```

notes.back:
// Why: Record<Role, number> requires every key of Role, so the compiler makes you start
// each count at 0 — and rejects roles that don't exist.
// Docs: https://www.typescriptlang.org/docs/handbook/utility-types.html
type Role = "admin" | "editor" | "viewer";

function countByRole(roles: Role[]): Record<Role, number> {
  const counts: Record<Role, number> = { admin: 0, editor: 0, viewer: 0 };
  for (const role of roles) counts[role]++;
  return counts;
}

